window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1f7bf1e67df6c46c"]={"versions": [{"id": "FIG-1f7bf1e67df6c46c", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Konfigurationsmodells (ECUC) für den Crypto Service Manager (CSM) im Kontext der AUTOSAR Classic Platform. Dargestellt ist die Strukturdefinition des Konfigurationscontainers <code>CsmGeneral</code> mit seinen aggregierten Konfigurationsparametern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert den Container <code>CsmGeneral: EcucParamConfContainerDef</code>, der über Kompositionsbeziehungen mit der Rollenbezeichnung <code>+parameter</code> sieben Parameter-Entitäten aggregiert:</p>\n<ul class=\"fig-list\"><li><code>CsmDevErrorDetect: EcucBooleanParamDef</code> mit Attribut <code>defaultValue = false</code>\n</li><li><code>CsmVersionInfoApi: EcucBooleanParamDef</code> mit Attribut <code>defaultValue = false</code>\n</li><li><code>CsmUseDeprecated: EcucBooleanParamDef</code> mit Attribut <code>defaultValue = false</code>\n</li><li><code>CsmMainFunctionPeriod: EcucFloatParamDef</code> mit den Wertebereichs- und Multiplizitätsgrenzen <code>min = 0</code>, <code>max = INF</code>, <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>\n</li><li><code>CsmAsymPublicKeyMaxLength: EcucIntegerParamDef</code> mit den Wertebereichs- und Multiplizitätsgrenzen <code>min = 1</code>, <code>max = 4294967295</code>, <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>\n</li><li><code>CsmAsymPrivateKeyMaxLength: EcucIntegerParamDef</code> mit den Wertebereichs- und Multiplizitätsgrenzen <code>min = 1</code>, <code>max = 4294967295</code>, <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>\n</li><li><code>CsmSymKeyMaxLength: EcucIntegerParamDef</code> mit den Wertebereichs- und Multiplizitätsgrenzen <code>min = 1</code>, <code>max = 4294967295</code>, <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzablaufdarstellung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Konfigurationsvorgabe für AUTOSAR-Werkzeugketten und BSW-Generatoren des Moduls CSM. Die booleschen Parameter zur Fehlererkennung (<code>CsmDevErrorDetect</code>), API-Versionsabfrage (<code>CsmVersionInfoApi</code>) und Nutzung veralteter Funktionen (<code>CsmUseDeprecated</code>) sind standardmäßig deaktiviert (<code>defaultValue = false</code>). Die Parameter für Zykluszeit (<code>CsmMainFunctionPeriod</code>) sowie Schlüssellängenobergrenzen (<code>CsmAsymPublicKeyMaxLength</code>, <code>CsmAsymPrivateKeyMaxLength</code>, <code>CsmSymKeyMaxLength</code>) sind optional konfigurierbar (Kardinalität [0..1]) mit exakt definierten Wertebereichen (uint32 für Längen bzw. nicht-negatives Float inklusive Unendlich für die Periodendauer).</p>"}, {"id": "FIG-05ca534bb3353c65", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Konfigurationsmodells (ECUC) für den Crypto Service Manager (CSM) im Kontext der AUTOSAR Classic Platform. Dargestellt ist die Strukturdefinition des Konfigurationscontainers <code>CsmGeneral</code> mit seinen aggregierten Konfigurationsparametern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert den Container <code>CsmGeneral: EcucParamConfContainerDef</code>, der über Kompositionsbeziehungen mit der Rollenbezeichnung <code>+parameter</code> sechs Parameter-Entitäten aggregiert:</p>\n<ul class=\"fig-list\"><li><code>CsmDevErrorDetect: EcucBooleanParamDef</code> mit Attribut <code>defaultValue = false</code>\n</li><li><code>CsmVersionInfoApi: EcucBooleanParamDef</code> mit Attribut <code>defaultValue = false</code>\n</li><li><code>CsmUseDeprecated: EcucBooleanParamDef</code> mit Attribut <code>defaultValue = false</code>\n</li><li><code>CsmMainFunctionPeriod: EcucFloatParamDef</code> mit den Wertebereichs- und Multiplizitätsgrenzen <code>min = 0</code>, <code>max = INF</code>, <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>\n</li><li><code>CsmAsymPublicKeyMaxLength: EcucIntegerParamDef</code> mit den Wertebereichs- und Multiplizitätsgrenzen <code>min = 1</code>, <code>max = 4294967295</code>, <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>\n</li><li><code>CsmAsymPrivateKeyMaxLength: EcucIntegerParamDef</code> mit den Wertebereichs- und Multiplizitätsgrenzen <code>min = 1</code>, <code>max = 4294967295</code>, <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzablaufdarstellung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Konfigurationsvorgabe für AUTOSAR-Werkzeugketten und BSW-Generatoren des Moduls CSM. Die booleschen Parameter zur Fehlererkennung (<code>CsmDevErrorDetect</code>), API-Versionsabfrage (<code>CsmVersionInfoApi</code>) und Nutzung veralteter Funktionen (<code>CsmUseDeprecated</code>) sind standardmäßig deaktiviert (<code>defaultValue = false</code>). Die Parameter für Zykluszeit (<code>CsmMainFunctionPeriod</code>) sowie asymmetrische Schlüssellängenobergrenzen (<code>CsmAsymPublicKeyMaxLength</code>, <code>CsmAsymPrivateKeyMaxLength</code>) sind optional konfigurierbar (Kardinalität [0..1]) mit exakt definierten Wertebereichen.</p>"}, {"id": "FIG-e84490bbb3cc6596", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Konfigurationsmodells (ECUC) für den Crypto Service Manager (CSM) im Kontext der AUTOSAR Classic Platform. Dargestellt ist die Strukturdefinition des Konfigurationscontainers <code>CsmGeneral</code> mit seinen aggregierten Konfigurationsparametern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert den Container <code>CsmGeneral: EcucParamConfContainerDef</code> mit den Multiplizitätsgrenzen <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>. Der Container aggregiert über Kompositionsbeziehungen mit der Rollenbezeichnung <code>+parameter</code> genau zwei Parameter-Entitäten:</p>\n<ul class=\"fig-list\"><li><code>CsmDevErrorDetect: EcucBooleanParamDef</code> mit <code>defaultValue = false</code>, <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>\n</li><li><code>CsmVersionInfoApi: EcucBooleanParamDef</code> mit <code>defaultValue = false</code>, <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzablaufdarstellung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Konfigurationsvorgabe für AUTOSAR-Werkzeugketten und BSW-Generatoren des CSM. Der Container <code>CsmGeneral</code> ist ein Pflichtelement mit einer exakten Multiplizität von 1..1. Beide enthaltenen Parameter (<code>CsmDevErrorDetect</code> und <code>CsmVersionInfoApi</code>) sind Pflichtparameter mit fester Kardinalität von 1..1 und besitzen als Standardeinstellung <code>defaultValue = false</code>.</p>"}, {"id": "FIG-1a55399c58e069b7", "releases": ["R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Konfigurationsmodells (ECUC) für den Crypto Service Manager (CSM) im Kontext der AUTOSAR Classic Platform. Dargestellt ist die Strukturdefinition des Konfigurationscontainers <code>CsmGeneral</code> mit seinen aggregierten Konfigurationsparametern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert den Container <code>CsmGeneral: EcucParamConfContainerDef</code> mit den Multiplizitätsgrenzen <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>. Der Container aggregiert über Kompositionsbeziehungen mit der Rollenbezeichnung <code>+parameter</code> genau zwei Parameter-Entitäten:</p>\n<ul class=\"fig-list\"><li><code>CsmDevErrorDetect: EcucBooleanParamDef</code> mit <code>defaultValue = false</code>, <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>\n</li><li><code>CsmVersionInfoApi: EcucBooleanParamDef</code> mit <code>defaultValue = false</code>, <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzablaufdarstellung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Konfigurationsvorgabe für AUTOSAR-Werkzeugketten und BSW-Generatoren des CSM. Der Container <code>CsmGeneral</code> ist ein Pflichtelement mit einer exakten Multiplizität von 1..1. Beide enthaltenen Parameter (<code>CsmDevErrorDetect</code> und <code>CsmVersionInfoApi</code>) sind Pflichtparameter mit fester Kardinalität von 1..1 und besitzen als Standardeinstellung <code>defaultValue = false</code>.</p>"}], "trans": [{"from": "FIG-1f7bf1e67df6c46c", "to": "FIG-05ca534bb3353c65", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Parameter <code>CsmSymKeyMaxLength: EcucIntegerParamDef</code> (inklusive Attribute <code>min = 1</code>, <code>max = 4294967295</code>, <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code> und Komposition <code>+parameter</code>) entfernt.\n</li></ul>"}, {"from": "FIG-05ca534bb3353c65", "to": "FIG-e84490bbb3cc6596", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Container <code>CsmGeneral: EcucParamConfContainerDef</code>: Multiplizitätsangaben <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code> hinzugefügt.\n</li><li>Parameter <code>CsmDevErrorDetect: EcucBooleanParamDef</code>: Multiplizitätsangaben <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code> ergänzt.\n</li><li>Parameter <code>CsmVersionInfoApi: EcucBooleanParamDef</code>: Multiplizitätsangaben <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code> ergänzt.\n</li><li>Parameter <code>CsmUseDeprecated: EcucBooleanParamDef</code> entfernt.\n</li><li>Parameter <code>CsmMainFunctionPeriod: EcucFloatParamDef</code> entfernt.\n</li><li>Parameter <code>CsmAsymPublicKeyMaxLength: EcucIntegerParamDef</code> entfernt.\n</li><li>Parameter <code>CsmAsymPrivateKeyMaxLength: EcucIntegerParamDef</code> entfernt.\n</li></ul>"}, {"from": "FIG-e84490bbb3cc6596", "to": "FIG-1a55399c58e069b7", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
